package com.example.community.service.impl;
import com.baomidou.mybatisplus.core.metadata.IPage;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.example.community.entity.Circle;import com.example.community.mapper.CircleMapper;import com.example.community.service.CircleService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;
@Service @RequiredArgsConstructor public class CircleServiceImpl implements CircleService {private final CircleMapper mapper;public Circle get(Integer id){Circle v=mapper.selectById(id);if(v==null)throw new IllegalArgumentException("圈子不存在");return v;}public List<Circle> byOwner(Integer owner){return mapper.selectList(new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<Circle>().eq(Circle::getOwner,owner));}public IPage<Circle> search(String keyword,long page,long size){var q=new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<Circle>();if(keyword!=null&&!keyword.isBlank())q.like(Circle::getCircleName,keyword).or().like(Circle::getDetail,keyword);return mapper.selectPage(new Page<>(page,size),q.orderByAsc(Circle::getCircleId));}@Transactional public Circle create(Circle v){mapper.insert(v);return get(v.getCircleId());}@Transactional public Circle update(Integer id,Circle input){Circle v=get(id);if(input.getOwner()!=null)v.setOwner(input.getOwner());if(input.getCircleName()!=null)v.setCircleName(input.getCircleName());if(input.getDetail()!=null)v.setDetail(input.getDetail());mapper.updateById(v);return get(id);}@Transactional public void delete(Integer id){if(mapper.deleteById(id)==0)throw new IllegalArgumentException("圈子不存在");}}
